// Verify the HMAC signature Convex sent: HMAC-SHA256(secret, `${timestamp}.${rawBody}`).
// Rejects stale timestamps (older than 5 minutes) to block replays.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'] || '';
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.LENDLOOP_N8N_WEBHOOK_SECRET;

let raw = '';
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}

const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
let valid = false;
if (secret && fresh && signature && raw) {
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
  valid = expected.length === signature.length &&
    crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
}

return [{ json: { valid, payload: valid ? JSON.parse(raw) : null } }];

// Build the message from the minimal payload. Only the recipient's first name and
// email, the tool name and the dates are available here, by design.
const p = $json.payload;
const range = `${p.startDate} to ${p.endDate}`;
const messages = {
  requested: `${p.otherPartyFirstName} would like to borrow your ${p.toolName} (${range}).`,
  approved: `${p.otherPartyFirstName} approved your request for the ${p.toolName} (${range}).`,
  declined: `${p.otherPartyFirstName} declined your request for the ${p.toolName} (${range}).`,
  cancelled: `The request for your ${p.toolName} (${range}) was cancelled.`,
  returned: `${p.otherPartyFirstName} marked the ${p.toolName} as returned. Thanks for borrowing!`,
};
return {
  json: {
    idempotencyKey: p.idempotencyKey,
    to: p.recipient.email,
    subject: `LendLoop: ${p.toolName}`,
    text: `Hi ${p.recipient.firstName}, ${messages[p.event] ?? 'there is an update on your loan.'}`,
  },
};

// Mock notification channel: logs the message instead of sending email.
// Swap this node for an Email/Slack/Discord node in production.
console.log(`[LendLoop notify] to=${$json.to} subject="${$json.subject}" text="${$json.text}"`);
return { json: { ...$json, deliveredAt: new Date().toISOString(), channel: 'mock-log' } };
